// Real Human Voice Audio Clips generated with Microsoft Neural Indian Voices
// For presentations, live demos, and realistic civic complaint audio

export const HUMAN_VOICE_BASE64: Record<string, string> = {'handpump_water': 'data:audio/mp3;base64,', 'road_pothole': 'data:audio/mp3;base64,', 'transformer_sparks': 'data:audio/mp3;base64,', 'substation_outage': 'data:audio/mp3;base64,', 'pani_mein_ishu': 'data:audio/mp3;base64,', 'sanitation_drainage': 'data:audio/mp3;base64,', 'street_light': 'data:audio/mp3;base64,', 'general_civic': 'data:audio/mp3;base64,'};

export const HUMAN_VOICE_PATHS: Record<string, string> = {
  handpump_water: '/audio/handpump_water.mp3',
  road_pothole: '/audio/road_pothole.mp3',
  transformer_sparks: '/audio/transformer_sparks.mp3',
  substation_outage: '/audio/substation_outage.mp3',
  pani_mein_ishu: '/audio/pani_mein_ishu.mp3',
  sanitation_drainage: '/audio/sanitation_drainage.mp3',
  street_light: '/audio/street_light.mp3',
  general_civic: '/audio/general_civic.mp3',
};

/**
 * Returns a high-fidelity human voice recording matching the issue content or category
 */
export function getRealisticHumanVoice(category?: string, text?: string): string {
  const lower = ((text || '') + ' ' + (category || '')).toLowerCase();
  
  if (lower.includes('pani mein ishu') || lower.includes('pani mein issue') || lower.includes('water supply') || lower.includes('पानी') || lower.includes('handpump') || lower.includes('जल') || lower.includes('नल')) {
    if (lower.includes('handpump') || lower.includes('हैंडपंप')) {
      return HUMAN_VOICE_BASE64.handpump_water;
    }
    return HUMAN_VOICE_BASE64.pani_mein_ishu;
  }

  if (lower.includes('road') || lower.includes('pothole') || lower.includes('सड़क') || lower.includes('गड्ढा') || lower.includes('रास्ते')) {
    return HUMAN_VOICE_BASE64.road_pothole;
  }

  if (lower.includes('transformer') || lower.includes('spark') || lower.includes('चिंगारी') || lower.includes('बिजली') || lower.includes('electric') || lower.includes('power')) {
    if (lower.includes('substation') || lower.includes('आउटेज')) {
      return HUMAN_VOICE_BASE64.substation_outage;
    }
    return HUMAN_VOICE_BASE64.transformer_sparks;
  }

  if (lower.includes('drain') || lower.includes('sanitation') || lower.includes('naali') || lower.includes('नाली') || lower.includes('कचरा') || lower.includes('garbage')) {
    return HUMAN_VOICE_BASE64.sanitation_drainage;
  }

  if (lower.includes('light') || lower.includes('pole') || lower.includes('स्ट्रीट लाइट') || lower.includes('अंधेरे')) {
    return HUMAN_VOICE_BASE64.street_light;
  }

  return HUMAN_VOICE_BASE64.general_civic;
}
